command:
$ErrorActionPreference = "Stop"
git fetch origin main work/model-streaming --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch failed" }
if ((git rev-parse origin/main).Trim() -ne "84a559c4c8fbac7409ddd46f5ecdde0b7e3bc0ce") { throw "main moved" }
if ((git rev-parse origin/work/model-streaming).Trim() -ne "ecd1fd0b7c0a419f05dc22fecd586838fb4913da") { throw "candidate moved" }
if ((git status --short).Count -ne 0) { throw "dirty persistent checkout" }

git checkout work/model-streaming
if ($LASTEXITCODE -ne 0) { throw "checkout candidate failed" }
git merge --ff-only origin/work/model-streaming
if ($LASTEXITCODE -ne 0) { throw "candidate fast-forward failed" }

Write-Host "SOURCE_CONTRACTS"
cmd /c test.bat source
if ($LASTEXITCODE -ne 0) { throw "source contracts failed" }

Write-Host "RELEASE_BUILD"
cmd /c build.bat Release
if ($LASTEXITCODE -ne 0) { throw "Release build failed" }

Write-Host "HELPER_PROTOCOL_V3"
$env:FLY_M16_CONFIG="Release"
python -X utf8 tests\winui\helper\test_process_isolation.py
if ($LASTEXITCODE -ne 0) { throw "helper protocol regression failed" }

Write-Host "OWNED_8000_MODEL_STREAMING_GUI"
python -X utf8 tests\winui\test_large_owned_folder_gui.py --items 8000 --configuration Release
if ($LASTEXITCODE -ne 0) { throw "8000-file model-streaming GUI failed" }

git diff --check origin/main..HEAD
if ($LASTEXITCODE -ne 0) { throw "diff check failed" }

Write-Host "MODEL_STREAMING_PREMAIN_PASS"
